pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        try c.deposit{value: amount}() {} catch { return; }
        uint balCBeforeWithdraw = address(c).balance;
        uint balThisBefore = address(this).balance;
        bool r1;
        bool r2;
        bool r3;
        try c.withdrawAll() { r1 = false; } catch { r1 = true; }
        uint balThisMid = address(this).balance;
        try c.withdrawAll() { r2 = false; } catch { r2 = true; }
        uint balThisAfter2 = address(this).balance;
        try c.withdrawAll() { r3 = false; } catch { r3 = true; }
        assertTrue(!r1 && !r2 && !r3 && balThisMid == balThisBefore + amount && balThisAfter2 == balThisBefore + amount && address(this).balance == balThisBefore + amount && address(c).balance == balCBeforeWithdraw - amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
